import React, { Component } from 'react'
import { LayoutWrapper } from './index.style'
import { Card, Table, Spin, Row, Col, Button, notification, Input, Icon, Upload } from 'antd'
import { ProductListTable as productTableColumns } from './constants/productList'
import { connect } from 'react-redux'
import productconfigActions from '../../redux/productConfig/actions'
import { get } from 'lodash'
import { removeLocalStorage } from './util/localstorageCheck'
import QueryString from 'query-string'
import QuerySearchBuilder from '../../../helpers/querySearchBuilder'
import Highlighter from 'react-highlight-words'

const dummyRequest = ({ file, onSuccess }) => {
  onSuccess()
}
const {
  getProductList,
  getImportProductRequest,
  resetProductConfigRedux
} = productconfigActions
class ProductConfig extends Component {
  state ={
    tableDataSource: [],
    querySearch: {},
    totalRecords: 0
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      importProductData,
      importProductDataMessage,
      tableDataSource,
      tableDataSourceMessage
    } = nextProps
    if (tableDataSourceMessage === 'success') {
      this.setState({
        tableDataSource: get(tableDataSource, 'data.details', []),
        totalRecords: get(tableDataSource, 'data.metadata.count', 0)
      })
      this.props.resetProductConfigRedux(['tableDataSourceMessage'])
    }
    if (tableDataSourceMessage !== 'success' && tableDataSourceMessage !== undefined) {
      notification.error({
        message: 'Error',
        description: tableDataSourceMessage
      })
      this.props.resetProductConfigRedux(['tableDataSourceMessage'])
    }
    if (importProductDataMessage === 'success') {
      notification.success({
        message: get(importProductData, 'message')
      })
      setTimeout(() => {
        this.fetch()
      }, 3000)
      this.props.resetProductConfigRedux(['importProductDataMessage'])
    }
    if (importProductDataMessage !== 'success' && importProductDataMessage !== undefined) {
      notification.error({
        message: get(importProductData, 'data.message')
      })
      this.props.resetProductConfigRedux(['importProductDataMessage'])
    }
  }

  componentDidMount () {
    const querySearch = QueryString.parse(this.props.location.search)
    if (Object.values(querySearch).length > 0) {
      this.fetch(querySearch)
    } else {
      this.fetch()
    }
    removeLocalStorage(['Step1', 'Step2', 'timezone', 'countriesData', 'provider', 'formData'])
  }

  detailPage=(val) => {
    const code = get(val, 'code', '')
    const { history } = this.props
    const queryString = QuerySearchBuilder({ product_code: code })

    history.push({
      pathname: '/product-config/detail',
      search: queryString
    })
  }

  handleAddProductPage= () => {
    const { history } = this.props
    history.push({
      pathname: '/product-config/create-product/1'
    })
  }

  handleTableChangeFunction = (pagination, filters, sorter) => {
    const { querySearch } = this.state
    const { history, location } = this.props
    const { pageSize, current } = pagination
    const offset = (current - 1) * pageSize
    const finalFilter = {
      ...querySearch,
      page: current,
      offset: Number(offset),
      limit: Number(pageSize)
    }
    this.setState({
      querySearch: finalFilter
    })
    const queryString = QuerySearchBuilder(finalFilter)
    // const querySearchString = QueryString.stringify(finalFilter)
    history.push({
      pathname: location.pathname,
      search: queryString
    })
    this.setState({
      offset,
      limit: Number(pageSize)
    }, () => this.fetch({
      // reference_id: this.props.match.params.policy_id,
      ...finalFilter
    }))
  }

  handleSearch = (selectedKeys, confirm, dataIndex) => {
    const { history, location } = this.props
    const { querySearch } = this.state
    const locationParams = QueryString.parse(history.location.search, { arrayFormat: 'index' })
    const newLocalSearch = {
      ...querySearch,
      ...locationParams,
      [dataIndex]: selectedKeys[0]
    }
    this.setState({
      querySearch: newLocalSearch
    })
    const queryStringData = QuerySearchBuilder(newLocalSearch)
    history.push({
      pathname: location.pathname,
      search: queryStringData
    })
    confirm()
  }

  handleReset = (clearFilters, dataIndex) => {
    const { history, location } = this.props
    const { querySearch } = this.state
    const localFilters = { ...querySearch }
    delete localFilters[dataIndex]
    this.setState({
      querySearch: localFilters
    })
    const queryStringData = QuerySearchBuilder(localFilters)
    history.push({
      pathname: location.pathname,
      search: queryStringData
    })
    // this.fetch()
    clearFilters()
  }

  getColumnSearchProps = (dataIndex) => ({
    filterDropdown: ({ setSelectedKeys, confirm, selectedKeys, clearFilters }) => (
      <div style={{ padding: 8 }}>
        <Input
          ref={node => {
            this.searchInput = node
          }}
          placeholder='Search'
          value={selectedKeys[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          style={{ width: 188, marginBottom: 8, display: 'block' }}
        />
        <Button
          type='primary'
          onClick={() => this.handleSearch(selectedKeys, confirm, dataIndex)}
          icon='search'
          size='small'
          style={{ width: 90, marginRight: 8 }}
        >
          Search
        </Button>
        <Button onClick={() => this.handleReset(clearFilters, dataIndex)} size='small' style={{ width: 90 }}>
          Reset
        </Button>
      </div>
    ),
    sorter: (a, b, sortOrder) => {
      if (sortOrder === 'ascend') {
        return a.id - b.id
      } else {
        return b.id - a.id
      }
    },
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) => {
      return record[dataIndex].toString().toLowerCase().includes(value.toLowerCase())
    },
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => this.searchInput.select())
      }
    },
    render: text =>
      this.state.searchedColumn === dataIndex
        ? (
          <Highlighter
            highlightStyle={{ backgroundColor: '#ffc069', padding: 0 }}
            searchWords={[this.state.searchText]}
            autoEscape
            textToHighlight={text.toString()}
          />)
        : (
            text
          )
  })

  fetch = (payload = { limit: 10, offset: 0 }) => {
    const { location, history } = this.props
    const { offset, limit } = payload
    const offsetNumber = payload.offset
    const limitSize = payload.limit
    const queryPage = Number(offsetNumber) || Number(offset)
    const queryLimit = Number(limitSize) || Number(limit)
    const finalQuery = {
      offset: Number(queryPage),
      limit: queryLimit,
      ...payload
    }
    delete finalQuery.page
    // finalQuery
    this.setState({
      querySearch: finalQuery,
      page: Number(get(payload, 'page')),
      limit: queryLimit
    })
    const queryString = QuerySearchBuilder(finalQuery)
    history.push({
      pathname: location.pathname,
      search: queryString
    })
    this.props.getProductList({ query: finalQuery })
  }

  async handleChange (info) {
    const files = info.file.originFileObj
    const reader = new FileReader()

    reader.onload = (e) => {
      let body = e.target.result
      try {
        body = JSON.parse(body)
      } catch (err) {
        notification.error({
          message: 'Failed To Parse Data'
        })
        return
      }
      this.props.getImportProductRequest({
        body: body
      })
    }
    reader.readAsText(files)
  }

  render () {
    const { tableDataSourceLoading, tableDataSourceError, importProductDataLoading = false } = this.props
    const { tableDataSource, limit, totalRecords, page } = this.state
    return (
      <LayoutWrapper>
        <Card>
          <Row type='flex' justify='space-between'>
            <Col>
              <h1 className='label-name'><b>Product List</b></h1>
            </Col>
            <Col>
              <div className='button__section'>
                <Upload
                  showUploadList={false}
                  customRequest={dummyRequest}
                  onChange={file => this.handleChange(file)}
                >
                  <Button className='button__import_product'><Icon type='upload' /> Import Product</Button>
                </Upload>
                <Button type='primary' onClick={this.handleAddProductPage}>Add Product</Button>
              </div>
            </Col>
          </Row>

          <div className='table-container'>
            <Spin spinning={(tableDataSourceLoading && !tableDataSourceError) || importProductDataLoading} tip='Product List Loading ...'>
              <Table
                bordered
                columns={productTableColumns.call(this)}
                dataSource={tableDataSource}
                rowKey={record => record.id}
                pagination={{
                  pageSize: limit,
                  total: totalRecords,
                  current: page
                }}
                onChange={this.handleTableChangeFunction}
              />
            </Spin>
          </div>
        </Card>
      </LayoutWrapper>
    )
  }
}

export default connect(
  state => ({
    tableDataSource: state.ProductConfigurable.productList,
    tableDataSourceMessage: state.ProductConfigurable.productListMessage,
    tableDataSourceLoading: state.Loading.GET_PRODUCT_LIST,
    tableDataSourceError: state.Error.GET_PRODUCT_LIST,
    importProductData: state.ProductConfigurable.importProductData,
    importProductDataMessage: state.ProductConfigurable.importProductDataMessage,
    importProductDataLoading: state.Loading.IMPORT_PRODUCT,
    importProductDataError: state.Error.IMPORT_PRODUCT
  }),
  {
    getProductList,
    getImportProductRequest,
    resetProductConfigRedux
  }
)(ProductConfig)
